import re
from urllib.parse import urlparse

ALLOWED_HOSTS = {"docs.example.com", "cdn.example.com"}
IMG = re.compile(r"!\[[^\]]*\]\((\S+?)\)")

class TrifectaGuard:
    """Per session, across ALL tools and MCP servers, not per tool."""
    def __init__(self):
        self.private = self.untrusted = False

    def on_tool_result(self, tool):
        self.private |= tool.reads_private_data     # read_inbox, query_crm
        self.untrusted |= tool.returns_untrusted    # fetch_url, read_issue

    def may_call(self, tool) -> str:
        if not tool.communicates_externally:        # send_email, http_post, create_pr
            return "allow"
        if self.private and self.untrusted:
            return "ask_human"  # the third leg needs a person in the loop
        return "allow"

def strip_exfil_images(markdown: str) -> str:
    # A rendered image is an outbound GET: data leaks with zero clicks
    def keep(m):
        host = urlparse(m.group(1)).hostname or ""
        return m.group(0) if host in ALLOWED_HOSTS else "[image removed]"
    return IMG.sub(keep, markdown)
